solutions.naive:
class Solution:
    def calPoints(self, ops: list[str]) -> int:
        scores = []
        for op in ops:
            if op == 'C':
                scores = scores[:-1]
            elif op == 'D':
                scores.append(scores[-1] * 2)
            elif op == '+':
                scores.append(scores[-1] + scores[-2])
            else:
                scores.append(int(op))
        total = 0
        for x in scores:
            total += x
        return total

solutions.better:
class Solution:
    def calPoints(self, ops: list[str]) -> int:
        stack = []
        for op in ops:
            if op == 'C':
                stack.pop()
            elif op == 'D':
                stack.append(2 * stack[-1])
            elif op == '+':
                stack.append(stack[-1] + stack[-2])
            else:
                stack.append(int(op))
        return sum(stack)

